// Cada «render» es una llamada a una función: los valores quedan fijos adentro.
function renderizar(n) {
  const sumarUno = () => n + 1; // cierra sobre el n de ESTE render
  return sumarUno;
}
const render1 = renderizar(0);
const render2 = renderizar(1);
const render3 = renderizar(2);
console.log("la función creada en el render 1 calcula:", render1());
console.log("la función creada en el render 2 calcula:", render2());
console.log("la función creada en el render 3 calcula:", render3());

// Un temporizador creado en el render 1 y nunca renovado sigue usando render1:
let pantalla = 0;
const viejo = setInterval(() => { pantalla = render1(); }, 50);
await new Promise((r) => setTimeout(r, 300));
clearInterval(viejo);
console.log("tras 6 ticks, la pantalla vale:", pantalla);

// A: lista vacía, pero el cierre usa n
useEffect(() => {
  const id = setInterval(() => setN(n + 1), 100);
  return () => clearInterval(id);
}, []);

// B: lista honesta [n]
useEffect(() => {
  const id = setInterval(() => setN(n + 1), 100);
  return () => clearInterval(id);
}, [n]);

// C: el efecto ya no lee n; pide «sumá uno al valor actual»
useEffect(() => {
  const id = setInterval(() => setN((x) => x + 1), 100);
  return () => clearInterval(id);
}, []);

// Dos respuestas que llegan en distinto orden que los pedidos.
const demora = { 41: 400, 42: 80 };
const pedir = (id) => new Promise((ok) => setTimeout(() => ok({ id, estado: id === 41 ? "en depósito" : "entregado" }), demora[id]));

async function probar(conGuarda) {
  let pantalla = "(vacía)";
  const efecto = (id) => {
    let ignorar = false;
    pedir(id).then((r) => { if (!ignorar) pantalla = `pedido ${r.id}: ${r.estado}`; });
    return () => { ignorar = true; }; // la limpieza
  };
  const sinGuarda = (id) => { pedir(id).then((r) => { pantalla = `pedido ${r.id}: ${r.estado}`; }); return () => {}; };
  const lanzar = conGuarda ? efecto : sinGuarda;
  const limpiar41 = lanzar(41);          // el usuario elige el 41
  limpiar41();                           // cambia de idea: React corre la limpieza del efecto anterior...
  lanzar(42);                            // ...y el efecto nuevo para el 42
  await new Promise((r) => setTimeout(r, 600));
  return pantalla;
}
console.log("sin guarda  → el usuario eligió el 42 y ve:", await probar(false));
console.log("con guarda  → el usuario eligió el 42 y ve:", await probar(true));

// 1. Sin protección
useEffect(() => {
  fetch('/api/pedido/' + id).then(r => r.json()).then(setDato);
}, [id]);

// 2. Con bandera: ignora la respuesta vieja, pero el pedido sigue
useEffect(() => {
  let ignore = false;
  fetch('/api/pedido/' + id).then(r => r.json())
    .then(j => { if (!ignore) setDato(j); });
  return () => { ignore = true; };
}, [id]);

// 3. Con AbortController: ignora y además cancela el pedido
useEffect(() => {
  const ctl = new AbortController();
  fetch('/api/pedido/' + id, { signal: ctl.signal })
    .then(r => r.json()).then(setDato)
    .catch(e => { if (e.name !== 'AbortError') throw e; });
  return () => ctl.abort();
}, [id]);

